mails={}
for p in sorted(Path('data/dev/emails').glob('*.eml')):
    e=ingest(p); r=parsed[e.id]
    # the customer is the INNER sender when one of our reps forwards one in
    dom=e.sender_domain
    if e.from_us:
        m=re.search(r'From:.*?@([\w.-]+)', e.body_quoted or '', re.I)
        dom=m.group(1).lower() if m else dom
    mails[e.id]=dict(id=e.id, dom=dom, who=e.sender_addr, subj=e.subject,
                     date=e.date, cls=r['classification'], n=len(r['line_items']),
                     rev=r['revises'], dup=r['duplicate_of'], review=r['needs_review'])

# a request = a thread: follow revises/duplicate_of, else subject+domain
root={}
def find(i):
    m=mails[i]
    if m['rev']: return find(m['rev'])
    if m['dup']: return find(m['dup'])
    return i
