    """Everything the walkthrough needs for one email, assembled on demand."""
    path = Path(job["inbox"]) / f"{eid}.eml"
    out = {"id": eid, "trace": job["traces"].get(eid), "parsed": (job["parsed"] or {}).get(eid)}
