:root {
  --bg: #f6f7f9;
  --panel: #ffffff;
  --ink: #15191e;
  --muted: #697586;
  --line: #dfe3e8;
  --accent: #1f5fa9;
  --warn-bg: #fdf3e3;
  --warn-ink: #8a5a06;
  --warn-line: #e8c98a;
  --drop-bg: #eef4fb;
  --grey-quote: #f2f3f5;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #14171b; --panel: #1b1f24; --ink: #e7ebf0; --muted: #96a0ad;
    --line: #2c333b; --accent: #76aae8; --warn-bg: #2e2415; --warn-ink: #e8bf7a;
    --warn-line: #5b482a; --drop-bg: #1d2733; --grey-quote: #23282e;
  }
}
:root[data-theme="dark"] {
  --bg: #14171b; --panel: #1b1f24; --ink: #e7ebf0; --muted: #96a0ad;
  --line: #2c333b; --accent: #76aae8; --warn-bg: #2e2415; --warn-ink: #e8bf7a;
  --warn-line: #5b482a; --drop-bg: #1d2733; --grey-quote: #23282e;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font: 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
.muted { color: var(--muted); }
code, .mono { font-family: var(--mono); font-size: 12.5px; }

header {
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
  padding: 12px 16px; background: var(--panel); border-bottom: 1px solid var(--line);
  position: sticky; top: 0; z-index: 5;
}
.brand { display: flex; gap: 10px; align-items: baseline; flex: 1; min-width: 220px; }
.brand span { font-size: 12.5px; }
.totals { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12.5px; }
.totals b { font-variant-numeric: tabular-nums; }
.btn {
  border: 1px solid var(--line); background: var(--panel); color: var(--ink);
  padding: 6px 12px; border-radius: 6px; cursor: pointer; font-size: 13px;
}
.btn:hover { border-color: var(--accent); color: var(--accent); }

main { display: flex; align-items: stretch; min-height: calc(100vh - 56px); }
#sidebar {
  width: 340px; flex: 0 0 340px; border-right: 1px solid var(--line);
  background: var(--panel); overflow-y: auto; max-height: calc(100vh - 56px);
}
#detail { flex: 1; padding: 20px 24px 60px; overflow-y: auto; max-height: calc(100vh - 56px); min-width: 0; }
.placeholder { padding: 40px 0; }
.empty { padding: 20px 16px; font-size: 13px; }
.empty p { margin: 0 0 10px; }

/* sidebar tree */
.group-head {
  padding: 10px 14px 6px; font-size: 11px; letter-spacing: .08em;
  text-transform: uppercase; color: var(--muted); border-top: 1px solid var(--line);
}
.party { padding: 2px 0 6px; }
.party-name { padding: 6px 14px 2px; font-weight: 600; font-size: 13px; word-break: break-all; }
.req {
  display: block; width: 100%; text-align: left; background: none; border: 0;
  border-left: 3px solid transparent; padding: 7px 14px 7px 20px; cursor: pointer;
  color: var(--ink); font: inherit;
}
.req:hover { background: var(--drop-bg); }
.req.active { background: var(--drop-bg); border-left-color: var(--accent); }
.req-line1 { display: flex; gap: 8px; align-items: baseline; }
.req-subject { flex: 1; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.req-meta { font-size: 11.5px; color: var(--muted); margin-top: 2px; }

.chip {
  font-size: 10.5px; letter-spacing: .04em; text-transform: uppercase;
  padding: 2px 6px; border-radius: 4px; border: 1px solid var(--line);
  color: var(--muted); white-space: nowrap;
}
.chip.ordered { border-color: #2e7d4f; color: #2e7d4f; }
.chip.revised { border-color: var(--accent); color: var(--accent); }
.chip.chased  { border-color: #8a6d1f; color: #8a6d1f; }
.chip.review  { border-color: var(--warn-line); background: var(--warn-bg); color: var(--warn-ink); }
.chip.supplier, .chip.no-action { opacity: .75; }

/* detail */
