  white-space: pre-wrap; word-break: break-word; font-family: var(--mono); font-size: 12.5px;
  margin: 0; padding: 12px 14px; border: 1px solid var(--line); border-radius: 6px; background: var(--panel);
}
pre.quoted { background: var(--grey-quote); color: var(--muted); border-style: dashed; margin-top: -1px; border-radius: 0 0 6px 6px; }
.quoted-label { font-size: 11.5px; color: var(--muted); padding: 6px 14px; border: 1px dashed var(--line); border-bottom: 0; border-radius: 6px 6px 0 0; background: var(--grey-quote); }
.doc-img { max-width: 100%; border: 1px solid var(--line); border-radius: 6px; margin: 8px 0; display: block; }
details.doc summary { cursor: pointer; font-size: 12.5px; color: var(--muted); }
details.doc pre { max-height: 320px; overflow: auto; margin-top: 8px; }

.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.mini { font-size: 11px; padding: 3px 8px; border-radius: 4px; border: 1px solid var(--line); background: var(--panel); color: var(--muted); cursor: pointer; font: inherit; font-size: 11.5px; }
.mini:hover { border-color: var(--accent); color: var(--accent); }
.mini.done { border-color: #2e7d4f; color: #2e7d4f; }

#drop-veil {
  position: fixed; inset: 0; background: var(--drop-bg); opacity: .96; z-index: 50;
  display: none; place-items: center; font-size: 20px; color: var(--accent);
  border: 3px dashed var(--accent);
}
#drop-veil.on { display: grid; }

.progress {
  position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%);
  background: var(--panel); border: 1px solid var(--line); border-radius: 999px;
  padding: 9px 18px; display: flex; gap: 10px; align-items: center; z-index: 40;
  box-shadow: 0 4px 16px rgba(0,0,0,.12); font-size: 13px;
}
.progress.hidden { display: none; }
.spinner { width: 14px; height: 14px; border: 2px solid var(--line); border-top-color: var(--accent); border-radius: 50%; animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

@media (max-width: 860px) {
  main { flex-direction: column; }
  #sidebar { width: auto; flex: none; max-height: 42vh; border-right: 0; border-bottom: 1px solid var(--line); }
  #detail { max-height: none; padding: 16px; }
}

