  border-bottom:1px solid var(--ai);flex-wrap:wrap}
.call .title{font-weight:600;font-size:13px;flex:1;min-width:160px}
.io{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0}
@media (max-width:1050px){.io{grid-template-columns:1fr}}
