input.content:
:root, :root[data-theme=dark] {
  --bg:#0a0c0f; --bg-2:#0e1116; --panel:#13171d; --panel-2:#171c23; --raised:#1c222a;
  --ink:#e8edf4; --ink-2:#b8c2cf; --muted:#6f7b8a; --faint:#49535f;
  --line:#1f252d; --line-2:#272e38;
  --code:#4d8bf0; --code-soft:#101a2b;
  --ai:#a970ff; --ai-soft:#1a1327; --ai-line:#3a2a5c;
  --ok:#3ecf8e; --ok-soft:#0d2019;
  --warn:#f0a742; --warn-soft:#231a0c; --warn-line:#4a3617;
  --bad:#ef5f5f; --bad-soft:#241114;
  --mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;
  --r:8px;
  --cols: minmax(230px, 1.5fr) repeat(6, minmax(118px, 1fr));
}
:root[data-theme=light]{ color-scheme:light }

*{box-sizing:border-box} html,body{height:100%}
body{margin:0;background:var(--bg);color:var(--ink);
  font:13.5px/1.55 ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  -webkit-font-smoothing:antialiased;color-scheme:dark}
.muted{color:var(--muted)} .small{font-size:11.5px}
code,.mono{font-family:var(--mono);font-size:12px}
h1{font-size:22px;margin:0 0 8px;letter-spacing:-.02em}
.lede{color:var(--ink-2);max-width:54ch;margin:0 auto 6px}

/* ───────── header ───────── */
header{display:flex;align-items:center;gap:12px;padding:10px 16px;background:var(--panel);
  border-bottom:1px solid var(--line);position:sticky;top:0;z-index:30}
.logo{width:26px;height:26px;border-radius:7px;flex:none;
  background:linear-gradient(135deg,var(--code),var(--ai))}
.title{display:flex;flex-direction:column;line-height:1.25}
.spacer{flex:1}
.meter{display:flex;gap:16px;font-size:11.5px;align-items:center;flex-wrap:wrap}
.meter b{font-variant-numeric:tabular-nums;color:var(--ink)}
.btn{border:1px solid var(--line-2);background:var(--panel-2);color:var(--ink-2);padding:6px 13px;
  border-radius:7px;cursor:pointer;font:inherit;font-size:12.5px;font-weight:500;white-space:nowrap}
.btn:hover:not(:disabled){border-color:var(--code);color:var(--code)}
.btn.primary{background:var(--code);border-color:var(--code);color:#06101f;font-weight:600}
.btn.primary:hover:not(:disabled){filter:brightness(1.12)}
.btn:disabled{opacity:.35;cursor:not-allowed}

/* ───────── the pipeline, as column headers ───────── */
.pipebar{display:grid;grid-template-columns:var(--cols);gap:1px;background:var(--line);
  border-bottom:1px solid var(--line-2);position:sticky;top:47px;z-index:20}
.pipebar.hidden{display:none}
.ph{background:var(--bg-2);padding:9px 12px}
.ph.lead{display:flex;align-items:center;font-size:11px;letter-spacing:.1em;
  text-transform:uppercase;color:var(--faint);font-weight:600}
.ph .n{display:flex;align-items:center;gap:6px;font-size:10px;letter-spacing:.09em;
  color:var(--faint);font-weight:600}
.ph .t{font-size:12px;font-weight:600;margin-top:3px;line-height:1.25;color:var(--ink-2)}
.ph.ai .n{color:var(--ai)} .ph.codey .n{color:var(--code)}
.tag{font-size:9px;letter-spacing:.08em;padding:1px 5px;border-radius:3px;text-transform:uppercase;
  border:1px solid currentColor;font-weight:700}

/* ───────── the grid of emails ───────── */
.grid{padding-bottom:70px}
.erow{display:grid;grid-template-columns:var(--cols);gap:1px;background:var(--line);
  border-bottom:1px solid var(--line)}
.cell{background:var(--bg-2);padding:9px 12px;min-width:0;display:flex;flex-direction:column;
  justify-content:center;gap:3px}
.erow:hover .cell{background:var(--panel)}
.erow.open .cell{background:var(--panel-2)}
.erow.sel .cell{background:var(--panel-2)}

.cell.lead{cursor:pointer;flex-direction:row;align-items:center;gap:9px}
.caret{color:var(--faint);transition:transform .15s;flex:none;font-size:10px}
.erow.open .caret{transform:rotate(90deg);color:var(--code)}
.lead-main{min-width:0;flex:1}
.eid{font-family:var(--mono);font-size:11px;color:var(--muted)}
.esubj{font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--ink)}
.esender{font-size:11px;color:var(--faint);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.v{font-size:12px;color:var(--ink-2);display:flex;align-items:center;gap:6px;flex-wrap:wrap;min-width:0}
.v .big{font-family:var(--mono);font-variant-numeric:tabular-nums;color:var(--ink)}
.sub{font-size:10.5px;color:var(--faint);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cell.pending{opacity:.32}
.cell.skipped{opacity:.42}
.cell.running{box-shadow:inset 2px 0 0 var(--code)}
.cell.done{box-shadow:inset 2px 0 0 var(--ok)}
.cell.warnc{box-shadow:inset 2px 0 0 var(--warn)}
.cell.badc{box-shadow:inset 2px 0 0 var(--bad)}
.dotpulse{width:7px;height:7px;border-radius:50%;background:var(--code);
  animation:pulse 1s ease-in-out infinite;flex:none}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.25}}

/* ───────── chips ───────── */
.chip{display:inline-block;font-size:10px;letter-spacing:.03em;font-weight:600;
  padding:2px 6px;border-radius:4px;border:1px solid var(--line-2);color:var(--muted);
  background:var(--panel);white-space:nowrap}
.chip.ai{border-color:var(--ai-line);color:var(--ai);background:var(--ai-soft)}
.chip.code{border-color:#1d3156;color:var(--code);background:var(--code-soft)}
.chip.ok{border-color:#174634;color:var(--ok);background:var(--ok-soft)}
.chip.warn{border-color:var(--warn-line);color:var(--warn);background:var(--warn-soft)}
.chip.bad{border-color:#4a1d22;color:var(--bad);background:var(--bad-soft)}

/* ───────── expanded detail ───────── */
.detail{grid-column:1/-1;background:var(--panel);border-top:1px solid var(--line-2);
  padding:20px 22px 26px}
.sec{margin:22px 0 10px;display:flex;align-items:center;gap:9px}
.sec:first-child{margin-top:0}
.sec .num{width:20px;height:20px;border-radius:5px;background:var(--raised);color:var(--muted);
  display:grid;place-items:center;font-size:10.5px;font-weight:700;flex:none}
.sec h3{margin:0;font-size:11.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.sec .after{color:var(--ink-2);text-transform:none;letter-spacing:0;font-weight:500}

.cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
@media(max-width:1100px){.cols{grid-template-columns:1fr}}
.card{background:var(--bg-2);border:1px solid var(--line-2);border-radius:var(--r);overflow:hidden}
.card>.ch{display:flex;gap:8px;align-items:center;padding:8px 12px;border-bottom:1px solid var(--line);
  font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:600;
  background:var(--panel-2)}
.card>.cb{padding:12px}
.card.warncard{border-color:var(--warn-line)}
.card.warncard>.ch{background:var(--warn-soft);color:var(--warn)}

pre.txt{margin:0;white-space:pre-wrap;word-break:break-word;font-family:var(--mono);
  font-size:11.5px;line-height:1.55;color:var(--ink-2)}
pre.scroll{max-height:300px;overflow:auto}
.quoted{margin-top:10px;border-top:1px dashed var(--line-2);padding-top:9px}
.quoted .lbl{font-size:11px;color:var(--muted);margin-bottom:6px;display:flex;gap:6px;align-items:center}
.quoted pre{opacity:.45}
dl.kv{display:grid;grid-template-columns:auto 1fr;gap:2px 12px;font-size:11.5px;margin:0 0 10px}
dl.kv dt{color:var(--faint)} dl.kv dd{margin:0;word-break:break-word;color:var(--ink-2)}

/* model call */
.call{border:1px solid var(--ai-line);border-radius:var(--r);overflow:hidden;margin-bottom:10px;
  background:var(--bg-2)}
.call>.ch{display:flex;gap:8px;align-items:center;padding:8px 12px;background:var(--ai-soft);
  border-bottom:1px solid var(--ai-line);flex-wrap:wrap}
.call .title{font-weight:600;font-size:12.5px;flex:1;min-width:150px;color:var(--ink)}
.io{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
@media(max-width:1100px){.io{grid-template-columns:1fr}}
.io>div{padding:11px 13px;min-width:0}
.io>div+div{border-left:1px solid var(--line-2)}
@media(max-width:1100px){.io>div+div{border-left:0;border-top:1px solid var(--line-2)}}
.io h4{margin:0 0 7px;font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--faint)}
details.raw{margin-top:8px}
details.raw summary{cursor:pointer;font-size:11.5px;color:var(--code);user-select:none;
  list-style:none;display:flex;gap:6px;align-items:center}
details.raw summary::before{content:"▸";font-size:9px;color:var(--faint)}
details.raw[open] summary::before{content:"▾"}
details.raw pre{margin-top:7px;background:var(--bg);border:1px solid var(--line);
  border-radius:6px;padding:10px;max-height:340px;overflow:auto}

table{width:100%;border-collapse:collapse;font-size:12.5px}
th{text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:var(--faint);
  font-weight:600;padding:6px 9px;border-bottom:1px solid var(--line-2)}
td{padding:7px 9px;border-bottom:1px solid var(--line);vertical-align:top;color:var(--ink-2)}
tr.item{cursor:pointer} tr.item:hover>td{background:var(--panel-2)}
td.num{text-align:right;font-family:var(--mono);font-variant-numeric:tabular-nums;white-space:nowrap;color:var(--ink)}
td.uom{font-family:var(--mono);color:var(--muted)}
td.src{font-family:var(--mono);font-size:11px;color:var(--faint);word-break:break-all}
.prov td{background:var(--code-soft)}
.prov .raw{font-family:var(--mono);font-size:11.5px;margin-bottom:7px;word-break:break-word;color:var(--ink)}
.prov ul{margin:5px 0 9px;padding-left:17px;font-size:11.5px}

.docrow{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:7px 0;
  border-bottom:1px solid var(--line)}
.docrow:last-child{border-bottom:0}
.docname{font-family:var(--mono);font-size:11.5px;flex:1;min-width:130px;word-break:break-all;color:var(--ink-2)}
.shot{max-width:100%;border:1px solid var(--line-2);border-radius:6px;margin-top:9px;display:block}
.mini{font-size:11px;padding:3px 8px;border-radius:5px;border:1px solid var(--line-2);
  background:var(--panel-2);color:var(--muted);cursor:pointer;font:inherit;font-size:11px}
.mini:hover{border-color:var(--code);color:var(--code)}
.mini.done{border-color:#174634;color:var(--ok);background:var(--ok-soft)}
.row{display:flex;gap:7px;align-items:center;flex-wrap:wrap}
.note{color:var(--muted);font-size:11.5px;padding:4px 0}

/* dropzone + veil */
.dropzone{margin:60px auto;max-width:520px;padding:44px 28px;text-align:center;
  border:1.5px dashed var(--line-2);border-radius:14px;background:var(--bg-2)}
