.chip.code{border-color:#1d3156;color:var(--code);background:var(--code-soft)}
.chip.ok{border-color:#174634;color:var(--ok);background:var(--ok-soft)}
.chip.warn{border-color:var(--warn-line);color:var(--warn);background:var(--warn-soft)}
.chip.bad{border-color:#4a1d22;color:var(--bad);background:var(--bad-soft)}

