.detail{grid-column:1/-1;background:var(--panel);border-top:1px solid var(--line-2);
  padding:20px 22px 26px}
.sec{margin:22px 0 10px;display:flex;align-items:center;gap:9px}
.sec:first-child{margin-top:0}
.sec .num{width:20px;height:20px;border-radius:5px;background:var(--raised);color:var(--muted);
  display:grid;place-items:center;font-size:10.5px;font-weight:700;flex:none}
.sec h3{margin:0;font-size:11.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.sec .after{color:var(--ink-2);text-transform:none;letter-spacing:0;font-weight:500}

.cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
