.card>.ch{display:flex;gap:8px;align-items:center;padding:8px 12px;border-bottom:1px solid var(--line);
  font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:600;
  background:var(--panel-2)}
.card>.cb{padding:12px}
.card.warncard{border-color:var(--warn-line)}
.card.warncard>.ch{background:var(--warn-soft);color:var(--warn)}

pre.txt{margin:0;white-space:pre-wrap;word-break:break-word;font-family:var(--mono);
  font-size:11.5px;line-height:1.55;color:var(--ink-2)}
pre.scroll{max-height:300px;overflow:auto}
.quoted{margin-top:10px;border-top:1px dashed var(--line-2);padding-top:9px}
.quoted .lbl{font-size:11px;color:var(--muted);margin-bottom:6px;display:flex;gap:6px;align-items:center}
.quoted pre{opacity:.45}
dl.kv{display:grid;grid-template-columns:auto 1fr;gap:2px 12px;font-size:11.5px;margin:0 0 10px}
dl.kv dt{color:var(--faint)} dl.kv dd{margin:0;word-break:break-word;color:var(--ink-2)}

