.prov td{background:var(--code-soft)}
.prov .raw{font-family:var(--mono);font-size:11.5px;margin-bottom:7px;word-break:break-word;color:var(--ink)}
.prov ul{margin:5px 0 9px;padding-left:17px;font-size:11.5px}

.docrow{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:7px 0;
  border-bottom:1px solid var(--line)}
.docrow:last-child{border-bottom:0}
.docname{font-family:var(--mono);font-size:11.5px;flex:1;min-width:130px;word-break:break-all;color:var(--ink-2)}
