attachment.snippet:
1	/* Ridgeline RFQ pipeline — the stages are the columns, each email is a row,
2	   and every cell opens the thing it is talking about.
3	   A window onto the pipeline, not a second implementation. */
4	
5	const $ = (s, r = document) => r.querySelector(s);
6	const el = (t, c, x) => { const n = document.createElement(t); if (c) n.className = c; if (x !== undefined) n.textContent = x; return n; };
7	
8	/* the columns.  `step` is the pipeline stage a column shows, or null for the
9	   two that describe the input rather than a stage. */
10	const COLS = [
11	  { key: "who",        step: null, label: "Person / organisation", kind: null   },
12	  { key: "email",      step: null, label: "The email, as is",      kind: null   },
13	  { key: "code",       step: 1,    label: "What code made of it",  kind: "code" },
14	  { key: "docs",       step: 2,    label: "Attachments",           kind: "code" },
15	  { key: "classify",   step: 3,    label: "Classification",        kind: "ai"   },
16	  { key: "extract",    step: 4,    label: "Model reads documents", kind: "ai"   },
17	  { key: "verify",     step: 5,    label: "Check every line",      kind: "code" },
18	  { key: "outcome",    step: 6,    label: "Outcome",               kind: "code" },
19	];
20	const STEP_OF = { code: "ingest", docs: "documents", classify: "classify", extract: "extract", verify: "verify", outcome: "link" };
21	
22	let JOB = null, SNAP = null, OPEN = null, PANEL = null, DETAIL = {}, timer = null;
23	
24	/* ───────────────────────────────────────────────────────────── upload */
25	
26	const send = (p, b) => fetch(p, { method: "POST", headers: { "Content-Type": "application/json" },
27	  body: JSON.stringify(b) }).then(r => r.json());
28	
29	function addFiles(list) {
30	  const files = [...list].filter(f => /\.eml$/i.test(f.name) || f.type === "message/rfc822");
31	  if (!files.length) return alert("Those don't look like .eml files.");
32	  Promise.all(files.map(f => new Promise((res, rej) => {
33	    const r = new FileReader();
34	    r.onload = () => res({ name: f.name, b64: String(r.result).split(",", 2)[1] });
35	    r.onerror = rej;
36	    r.readAsDataURL(f);
37	  }))).then(p => send("/api/stage", { job: JOB, files: p }))
38	    .then(s => { if (s.error) throw new Error(s.error); JOB = s.job; apply(s); })
39	    .catch(e => alert("Could not read those files: " + e.message));
40	}
41	
42	function process() {
43	  if (!JOB) return;
44	  DETAIL = {};
45	  $("#process").disabled = true;
46	  send("/api/process", { job: JOB }).then(() => poll());
47	}
48	
49	function poll() {
50	  if (!JOB) return;
51	  fetch(`/api/job?job=${encodeURIComponent(JOB)}`).then(r => r.json()).then(s => {
52	    if (s.error) return;
53	    apply(s);
54	    if (s.state === "running") timer = setTimeout(poll, 400);
55	    else if (OPEN) loadDetail(OPEN, true);
56	  });
57	}
58	
59	/* ───────────────────────────────────────────────────────────── chrome */
60	
61	function apply(s) {
62	  SNAP = s;
63	  $("#pipebar").classList.toggle("hidden", !s.order.length);
64	  $("#dropzone").classList.toggle("hidden", !!s.order.length);
65	  $("#reset").hidden = !s.order.length;
66	  $("#process").disabled = s.state === "running" || !s.order.length;
67	  $("#process").textContent = s.state === "running" ? "Processing…"
68	    : s.state === "done" ? "Process again" : `Process ${s.order.length}`;
69	  renderPipebar();
70	  renderMeter(s);
71	  renderGrid(s);
72	}
73	
74	function renderPipebar() {
75	  const bar = $("#pipebar");
76	  if (bar.childElementCount) return;
77	  for (const c of COLS) {
78	    const h = el("div", `ph ${c.kind === "ai" ? "ai" : c.kind === "code" ? "codey" : "plain"}`);
79	    const n = el("div", "n");
80	    if (c.step) { n.append(`STEP ${c.step}`, el("span", "tag", c.kind === "ai" ? "model" : "code")); }
81	    else n.append("INPUT");
82	    h.append(n, el("div", "t", c.label));
83	    bar.append(h);
84	  }
85	}
86	
87	function renderMeter(s) {
88	  const m = $("#meter"); m.innerHTML = "";
89	  const done = s.order.filter(i => s.emails[i].state === "done").length;
90	  const bits = [[`${done}/${s.order.length}`, "processed"]];
91	  if (s.cost) bits.push(
92	    [`${s.cost.model_calls}`, "calls"], [`${s.cost.cache_hits}`, "cached"],
