tol=collections.Counter(); nulls=[]
for eid,v in g.items():
    for l in v['line_items']:
        t=l.get('qty_tol'); tol[repr(t)]+=1
        if t is None: nulls.append((l['id'], l['raw'], l['qty']))
        if l.get('qty') is None: nulls.append((l['id'], l['raw'], 'qty=None'))
print("qty_tol values:", dict(tol))
print("\nlines the key marks as unscored or has no quantity for:")
for x in set(nulls): print("   ", x)

print("\nneeds_review in the key:")
for eid,v in g.items():
    if v.get('needs_review'): print(f"   {eid}  ({v['classification']}, {len(v['line_items'])} lines)")

print("\nemails where the key keeps lines AND flags review (partial reads):")
for eid,v in g.items():
    if v.get('needs_review') and v['line_items']: print(f"   {eid}: {len(v['line_items'])} lines + flag")
print("   (none means every flagged email in the key has zero lines)")

print("\nclassification spread:", dict(collections.Counter(v['classification'] for v in g.values())))
print("duplicate_of:", {e:v['duplicate_of'] for e,v in g.items() if v.get('duplicate_of')})
print("revises    :", {e:v['revises'] for e,v in g.items() if v.get('revises')})
